// CSD_RATIONALE_BEGIN
// Multi-span adaptive CSD for math word problems (GSM-symbolic).
// State tracked: insideConstrainedOut (whether inside a << >> span),
// currentConstrainedOut (parser-tracked constrained prefix), steps (budget).
// Outside a span the model generates free reasoning text (natural language
// explanations and arithmetic narration). When the rendered output ends with
// "<<", we flip into constrained mode and reset currentConstrainedOut to [].
// Inside a span we use AdaptiveConstrainedStep with caller-supplied groups to
// prefer math vocabulary tokens while the parser hard-gates validity. When the
// parser reports IsCompletePrefix we close the span with ">>". The cycle repeats
// for each intermediate symbolic expression and for the final answer block.
// A task-guidance string primes the model to produce the required format.
// The 900-step budget accommodates lengthy step-by-step reasoning plus several
// short constrained expression spans.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Free branch: when RenderedEndsWith(generated,"<<") is true we set
//     currentConstrainedOut := [], which satisfies IsValidPrefix([]) by the
//     method precondition. When the suffix is not "<<" insideConstrainedOut
//     stays false so the implication is vacuously true.
//   Close branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//     making the implication vacuously true, and clears currentConstrainedOut := [].
//   Constrained branch: AdaptiveConstrainedStep returns EOS or a token t such
//     that parser.IsValidPrefix(currentConstrainedOut + [t]); AppendConstrainedToken
//     extends currentConstrainedOut by exactly t, so the invariant is restored.
// progress (|generated| <= |generatedPrefix| + steps):
//   Free branch: appends exactly one non-EOS token to generated and increments
//     steps by 1; EOS breaks without appending; bound maintained.
//   Close branch: CloseConstrainedSpan appends ">>" (one token) and costs 1
//     step; steps grows by 1 and |generated| grows by at most 1; bound maintained.
//   Constrained branch: AdaptiveConstrainedStep costs 1 step; AppendConstrainedToken
//     appends at most one token (zero on EOS path); steps grows by 1 so the
//     bound |generated| <= |generatedPrefix| + steps is maintained.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math problem step by step in plain English. For every arithmetic sub-expression and for the final numeric answer, wrap the expression inside << >> delimiters, for example: John has <<5+3=8>> apples. The final answer is <<8>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stableLen := |generated| - |currentConstrainedOut|;
    var constrainedPrompt := prompt + generated[..stableLen];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

